-- Products
INSERT OR IGNORE INTO products (slug, name_ar, name_en, short_desc_ar, description_ar, category_id, main_image, specs, colors, featured, is_new, status, sort_order) VALUES
  ('sliding-window-thermal', 'نافذة سحب بعزل حراري', 'Thermal Sliding Window', 'نافذة سحب ألمنيوم بقطاع عريض وعزل حراري وصوتي مزدوج', 'نافذة سحب من الألمنيوم عالي الجودة بنظام القطع الحراري (Thermal Break) الذي يمنع انتقال الحرارة بين الداخل والخارج. مزودة بزجاج دبل مفرغ من الهواء لعزل صوتي يصل إلى 40 ديسيبل. مثالية للمشاريع السكنية والفندقية في المناخ الحار.', (SELECT id FROM categories WHERE slug='windows'), '/static/img/products/sliding-window.jpg', '[{"label":"نوع القطاع","value":"سحب حراري 2.0 مم"},{"label":"الزجاج","value":"دبل 6+12+6 مم"},{"label":"العزل الصوتي","value":"حتى 40 ديسيبل"},{"label":"الضمان","value":"10 سنوات"}]', '["أبيض","أسود","رمادي","بني خشبي"]', 1, 1, 'published', 1),
  ('hinged-window', 'نافذة مفصلية (فتح خارجي)', 'Casement Window', 'نافذة مفصلية محكمة الإغلاق بجودة أوروبية', 'نافذة مفصلية بفتح خارجي أو داخلي مع إمكانية نظام القلاب (Tilt & Turn). إحكام كامل ضد الغبار والهواء بفضل الجوانات المزدوجة EPDM. تناسب الفلل والقصور والمباني الحديثة.', (SELECT id FROM categories WHERE slug='windows'), '/static/img/products/hinged-window.jpg', '[{"label":"نوع الفتح","value":"مفصلي / قلاب"},{"label":"الجوانات","value":"EPDM مزدوجة"},{"label":"الإكسسوارات","value":"ألمانية GU"}]', '["أبيض","أسود","شامبين"]', 1, 0, 'published', 2),
  ('main-entrance-door', 'باب مدخل رئيسي فاخر', 'Luxury Entrance Door', 'باب مدخل ألمنيوم بتصميم فاخر وأمان متعدد النقاط', 'باب مدخل رئيسي من الألمنيوم المقوى بسماكة قطاع 2.5 مم مع نظام إغلاق متعدد النقاط (5 نقاط) وإمكانية إضافة قفل ذكي ببصمة. تصاميم عصرية وكلاسيكية مع إمكانية دمج الزجاج المعشق أو ألواح الخشب.', (SELECT id FROM categories WHERE slug='doors'), '/static/img/products/entrance-door.jpg', '[{"label":"سماكة القطاع","value":"2.5 مم"},{"label":"نظام الإغلاق","value":"5 نقاط"},{"label":"القفل الذكي","value":"اختياري"}]', '["أسود","بني","رمادي غامق"]', 1, 0, 'published', 3),
  ('folding-door', 'باب قابل للطي (فولدنق)', 'Folding Door', 'باب فولدنق يفتح المساحات بالكامل على الحديقة أو المسبح', 'باب قابل للطي بعدد أجنحة من 3 إلى 7 يتيح فتح الجدار بالكامل ودمج المساحات الداخلية مع الخارجية. عجلات تحمل ثقيل وسكك ستانلس ستيل مقاومة للصدأ. مثالي للمجالس والصالات المطلة على الحدائق.', (SELECT id FROM categories WHERE slug='doors'), '/static/img/products/folding-door.jpg', '[{"label":"عدد الأجنحة","value":"3 - 7"},{"label":"السكك","value":"ستانلس ستيل"},{"label":"الزجاج","value":"دبل سيكوريت"}]', '["أسود","رمادي","أبيض"]', 1, 1, 'published', 4),
  ('curtain-wall-structural', 'واجهة ستركشر زجاجية', 'Structural Glazing', 'واجهة زجاجية ستركشر بدون إطارات ظاهرة للمباني الحديثة', 'نظام واجهات ستركشر جلايزنق يعطي مظهراً زجاجياً نقياً بدون ألمنيوم ظاهر من الخارج. زجاج عاكس أو دبل حسب المتطلبات الحرارية. تنفيذ كامل بمعايير السلامة السعودية مع حسابات الرياح والأحمال.', (SELECT id FROM categories WHERE slug='facades'), '/static/img/products/curtain-wall.jpg', '[{"label":"النظام","value":"ستركشر / سيمي ستركشر"},{"label":"الزجاج","value":"عاكس دبل 24 مم"},{"label":"التثبيت","value":"هيكل ألمنيوم مخفي"}]', '["أزرق عاكس","أخضر عاكس","دخاني","فضي"]', 1, 0, 'published', 5),
  ('aluminum-kitchen-modern', 'مطبخ ألمنيوم مودرن', 'Modern Aluminum Kitchen', 'مطبخ ألمنيوم كامل مقاوم للماء والحرارة بتشطيبات فاخرة', 'مطبخ ألمنيوم عصري مقاوم 100% للرطوبة والحشرات والحرارة. تشطيبات لامعة ومطفية وخشبية مع أرفف داخلية وجوارير سوفت كلوز. تصميم ثلاثي الأبعاد مجاني قبل التنفيذ.', (SELECT id FROM categories WHERE slug='kitchens'), '/static/img/products/kitchen.jpg', '[{"label":"الخامة","value":"ألمنيوم + HPL"},{"label":"الجوارير","value":"سوفت كلوز"},{"label":"التصميم","value":"3D مجاني"}]', '["أبيض لامع","رمادي مطفي","خشبي","أسود"]', 1, 0, 'published', 6),
  ('glass-handrail', 'درابزين زجاج بروفايل', 'Glass Railing', 'درابزين زجاجي بقاعدة ألمنيوم للسلالم والبلكونات', 'درابزين زجاج سيكوريت 12 مم بنظام البروفايل الألمنيوم المدفون أو الظاهر. مظهر عصري نظيف بدون قوائم، مع إمكانية إضافة هاند ريل ستانلس أو ألمنيوم. مطابق لاشتراطات السلامة.', (SELECT id FROM categories WHERE slug='handrails'), '/static/img/products/glass-handrail.jpg', '[{"label":"الزجاج","value":"سيكوريت 12 مم"},{"label":"النظام","value":"بروفايل U مدفون"},{"label":"الارتفاع","value":"90 - 110 سم"}]', '["شفاف","دخاني","حليبي"]', 0, 1, 'published', 7),
  ('electric-shutter', 'شتر كهربائي بريموت', 'Electric Roller Shutter', 'شتر ألمنيوم كهربائي بريموت كنترول وإمكانية ربط ذكي', 'شتر ألمنيوم رول كهربائي بشفرات معزولة بالفوم لعزل حراري إضافي. يعمل بالريموت أو التطبيق الذكي مع إمكانية البرمجة الزمنية. حماية وخصوصية وعزل في منتج واحد.', (SELECT id FROM categories WHERE slug='shutters'), '/static/img/products/shutter.jpg', '[{"label":"الشفرات","value":"معزولة بالفوم"},{"label":"التشغيل","value":"ريموت / تطبيق"},{"label":"الموتور","value":"إيطالي ضمان 5 سنوات"}]', '["بيج","أبيض","رمادي","بني"]', 0, 0, 'published', 8),
  ('aluminum-pergola', 'برجولا ألمنيوم متحركة', 'Motorized Pergola', 'برجولا ألمنيوم بشرائح متحركة كهربائياً للتحكم بالظل والتهوية', 'برجولا ألمنيوم فاخرة بشرائح قابلة للفتح والإغلاق كهربائياً حتى 135 درجة، مع تصريف مخفي لمياه الأمطار داخل الأعمدة. إضاءة LED مدمجة اختيارية وستائر زجاجية جانبية. مثالية للحدائق والأسطح والمطاعم.', (SELECT id FROM categories WHERE slug='pergolas'), '/static/img/products/pergola.jpg', '[{"label":"الشرائح","value":"متحركة 0-135 درجة"},{"label":"التصريف","value":"مخفي داخل الأعمدة"},{"label":"الإضاءة","value":"LED اختيارية"}]', '["أبيض","أسود","رمادي","خشبي"]', 1, 1, 'published', 9),
  ('office-partition', 'قواطع مكاتب زجاجية', 'Office Glass Partition', 'قواطع زجاج وألمنيوم عازلة للصوت للمكاتب الحديثة', 'قواطع مكتبية من الزجاج المزدوج مع شيش داخلي مدمج بين طبقتي الزجاج. عزل صوتي ممتاز وخصوصية قابلة للتحكم. أبواب زجاجية سحب أو مفصلية ضمن النظام.', (SELECT id FROM categories WHERE slug='partitions'), '/static/img/products/partition.jpg', '[{"label":"الزجاج","value":"دبل مع شيش مدمج"},{"label":"العزل الصوتي","value":"حتى 42 ديسيبل"},{"label":"الأبواب","value":"سحب / مفصلي"}]', '["أسود","فضي","أبيض"]', 0, 0, 'published', 10);

-- Services
INSERT OR IGNORE INTO services (slug, title_ar, title_en, short_desc_ar, description_ar, icon, features_ar, sort_order) VALUES
  ('design-consultation', 'الاستشارة والتصميم', 'Design & Consultation', 'استشارة فنية مجانية وتصميم ثلاثي الأبعاد قبل التنفيذ', 'فريق هندسي متخصص يقدم استشارات مجانية لاختيار الأنظمة المناسبة لمشروعك، مع رفع مقاسات دقيق وتصاميم ثلاثية الأبعاد وعينات للاعتماد قبل بدء التصنيع.', 'fa-compass-drafting', '["زيارة موقع مجانية","رفع مقاسات بالليزر","تصميم 3D","عينات للاعتماد"]', 1),
  ('manufacturing', 'التصنيع', 'Manufacturing', 'مصنع حديث بخطوط إنتاج أوروبية وجودة مراقبة', 'مصنعنا مجهز بأحدث ماكينات القص والتجميع الأوروبية CNC، مع نظام مراقبة جودة على كل مرحلة من مراحل الإنتاج لضمان مطابقة المواصفات.', 'fa-industry', '["ماكينات CNC أوروبية","قطاعات معتمدة","فحص جودة مرحلي","طاقة إنتاجية عالية"]', 2),
  ('installation', 'التركيب', 'Installation', 'فرق تركيب محترفة بإشراف هندسي مباشر', 'فرق تركيب مدربة ومعتمدة تنفذ الأعمال بإشراف مهندسين متخصصين، مع الالتزام بمعايير السلامة والجداول الزمنية المتفق عليها وتسليم نظيف للموقع.', 'fa-screwdriver-wrench', '["إشراف هندسي","التزام بالمواعيد","معايير سلامة","تسليم نظيف"]', 3),
  ('maintenance', 'الصيانة وما بعد البيع', 'Maintenance', 'عقود صيانة دورية وخدمة ما بعد البيع', 'خدمة ما بعد البيع تشمل الصيانة الدورية والطارئة وتوفير قطع الغيار والإكسسوارات الأصلية، مع ضمانات تصل إلى 10 سنوات على القطاعات.', 'fa-gears', '["ضمان حتى 10 سنوات","صيانة طارئة","قطع غيار أصلية","عقود سنوية"]', 4);

-- Projects
INSERT OR IGNORE INTO projects (slug, title_ar, description_ar, cover_image, client, location, project_type, project_date, featured, sort_order) VALUES
  ('riyadh-tower-facade', 'واجهات برج الأعمال - الرياض', 'تنفيذ واجهات كرتن وول زجاجية بمساحة 8,500 م² لبرج مكتبي من 22 طابقاً في حي العليا، شاملة الواجهات والمداخل الرئيسية والقواطع الداخلية.', '/static/img/projects/tower.jpg', 'شركة التطوير العقاري المتحدة', 'الرياض - العليا', 'commercial', '2025', 1, 1),
  ('villa-compound-north', 'كمباوند فلل شمال الرياض', 'توريد وتركيب نوافذ وأبواب ألمنيوم بعزل حراري لـ 48 فيلا سكنية، شاملة أبواب المداخل الرئيسية والدرابزين الزجاجي للسلالم.', '/static/img/projects/compound.jpg', 'مجموعة الإسكان الحديث', 'الرياض - الياسمين', 'residential', '2024', 1, 2),
  ('mall-entrance-jeddah', 'مداخل مول التسوق - جدة', 'تنفيذ مداخل زجاجية أوتوماتيكية وواجهات ستركشر لمول تجاري، مع شتر حماية كهربائي لكامل المحلات الداخلية (120 محل).', '/static/img/projects/mall.jpg', 'شركة المراكز العالمية', 'جدة - طريق الملك', 'commercial', '2024', 0, 3),
  ('government-building', 'مبنى إداري حكومي', 'أعمال واجهات وألمنيوم متكاملة لمبنى إداري حكومي وفق أعلى اشتراطات الجودة والسلامة، شاملة النوافذ المقاومة للحريق.', '/static/img/projects/government.jpg', 'جهة حكومية', 'الدمام', 'governmental', '2023', 0, 4);

-- Home hero sections
INSERT OR IGNORE INTO home_sections (section_type, title_ar, subtitle_ar, image, cta_text_ar, cta_link, sort_order) VALUES
  ('hero', 'حلول ألمنيوم متكاملة بجودة عالمية', 'من التصميم إلى التركيب، نحول مشروعك إلى واقع بأنظمة ألمنيوم وزجاج معتمدة وضمانات تصل إلى 10 سنوات', '/static/img/hero/hero1.jpg', 'اطلب عرض سعر', '/quote', 1),
  ('hero', 'واجهات زجاجية تليق بمبانيكم', 'كرتن وول وستركشر جلايزنق بتنفيذ هندسي دقيق ومعايير سلامة معتمدة', '/static/img/hero/hero2.jpg', 'تصفح مشاريعنا', '/projects', 2),
  ('hero', 'نوافذ وأبواب بعزل حراري وصوتي', 'وفّر في فاتورة الكهرباء واستمتع بالهدوء مع أنظمة القطع الحراري الأوروبية', '/static/img/hero/hero3.jpg', 'استعرض المنتجات', '/products', 3);

