  ('fa-certificate', 'قطاعات معتمدة', 'نستخدم قطاعات ألمنيوم وإكسسوارات أوروبية معتمدة بضمانات موثقة', 2),
  ('fa-drafting-compass', 'تصميم مجاني', 'رفع مقاسات وتصميم ثلاثي الأبعاد مجاناً قبل بدء التنفيذ', 3),
  ('fa-clock', 'التزام بالمواعيد', 'جداول زمنية واضحة والتزام كامل بمواعيد التسليم المتفق عليها', 4),
